const models=[['Volkswagen Golf','1.5 TSI · пример 2020','petrol',1350,6.2,20000,11000],['Toyota Yaris','1.5 Hybrid · пример 2021','hybrid',1185,4.5,18000,10000],['Toyota Corolla','1.8 Hybrid · пример 2021','hybrid',1385,4.8,23000,13500],['Tesla Model 3','RWD · пример 2022','electric',1835,17,27000,14000],['Kia Niro','EV · пример 2022','electric',1839,18,26000,14000],['Volkswagen Polo','1.0 TSI · пример 2020','petrol',1170,5.5,15500,8500],['BMW 320d','Diesel · пример 2020','diesel',1615,5.5,28000,15000],['Mitsubishi Outlander','PHEV · пример 2020','phev',1955,7.5,24000,12000],['Другая модель','Введите свои параметры','petrol',1400,6.5,20000,10000]];
const provinces=['Noord-Holland','Zuid-Holland','Utrecht','Noord-Brabant','Gelderland','Overijssel','Limburg','Flevoland','Friesland','Groningen','Drenthe','Zeeland'];
const $=id=>document.getElementById(id),num=id=>Math.max(0,Number($(id).value)||0),eur=(v,d=0)=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'EUR',maximumFractionDigits:d,minimumFractionDigits:d}).format(v);
$('model').innerHTML=models.map((m,i)=>`<option value="${i}">${m[0]} — ${m[1]}</option>`).join('');$('province').innerHTML=provinces.map(p=>`<option>${p}</option>`).join('');let selectedRdwName=null;let period=1,current,saved=[];try{saved=JSON.parse(localStorage.getItem('autobudget-comparisons')||'[]');if(!Array.isArray(saved))saved=[];saved=saved.filter(s=>s&&typeof s.name==='string'&&Number.isFinite(s.total)&&Number.isFinite(s.full)&&Number.isFinite(s.km)).slice(0,3)}catch{}
function estimateTax(){const kg=Math.max(500,num('weight')-100);const petrol=Math.max(65,126+Math.ceil((kg-1000)/100)*24);$('tax').value=Math.round(petrol*($('fuel').value==='electric'?.7:$('fuel').value==='diesel'?2.1:1));taxNote(false)}
function taxNote(manual){$('taxNote').textContent=(manual?'Введённая вами сумма MRB.':'MRB — приблизительный ориентир, без провинциальных надбавок.')+' Проверьте сумму для '+$('province').value+' в калькуляторе Belastingdienst ниже. Возможная надбавка за сажу дизеля не оценена.'}
function fuelUI(){const ev=$('fuel').value==='electric';$('consLabel').firstChild.textContent=ev?'Расход, кВт·ч / 100 км':'Расход, л / 100 км';$('priceLabel').firstChild.textContent=ev?'Зарядка, € / кВт·ч':$('fuel').value==='diesel'?'Дизель, € / л':'Бензин, € / л';$('phevFields').hidden=$('fuel').value!=='phev'}
function selectModel(){selectedRdwName=null;$('modelProvenance').textContent='Выбран примерный сценарий. Для характеристик из реестра воспользуйтесь поиском выше.';const m=models[Number($('model').value)];['fuel','weight','consumption','purchase','resale'].forEach((id,i)=>$(id).value=m[i+2]);$('energyPrice').value=m[2]==='electric'?.35:m[2]==='diesel'?1.85:2.1;fuelUI();estimateTax();render()}
function render(){const km=num('km'),fuel=$('fuel').value;let energy=km/100*num('consumption')*num('energyPrice');if(fuel==='phev'){const share=Math.min(100,num('electricShare'))/100;energy=energy*(1-share)+km/100*share*num('electricConsumption')*num('electricPrice')}
const parts=[['Топливо и зарядка',energy,'#d5e8a8'],['Страховка',num('insurance')*12,'#a9c68d'],['Дорожный налог · MRB',num('tax')*4,'#83aa84'],['Сервис, шины и APK',num('service')+num('tires')+num('apk'),'#619980'],['Парковка и помощь',num('parking')*12+num('roadside'),'#aac3ba']];const annual=parts.reduce((s,p)=>s+p[1],0),dep=(num('purchase')-num('resale'))/5,div=period===1?12:1,full=annual+dep;current={name:selectedRdwName||models[Number($('model').value)][0],total:annual,full,km,province:$('province').value};$('kmValue').textContent=km.toLocaleString('ru-RU');$('carName').textContent=current.name;$('carDetails').textContent=$('fuel').selectedOptions[0].text+' · '+num('weight').toLocaleString('ru-RU')+' кг';$('total').textContent=eur(annual/div);$('breakdown').innerHTML=parts.map(p=>`<div class="row"><span class="dot" style="background:${p[2]}"></span><span>${p[0]}</span><strong>${eur(p[1]/div)}</strong></div>`).join('');$('bar').innerHTML=parts.map(p=>`<span style="width:${annual?p[1]/annual*100:0}%;background:${p[2]}"></span>`).join('');$('depreciation').textContent=eur(dep/div);$('full').textContent=eur(full/div);$('perKm').textContent=km?eur(full/km,2):'—';$('fiveYears').textContent=eur(full*5+num('bpm')+num('oneoff'));$('monthly').classList.toggle('active',period===1);$('yearly').classList.toggle('active',period===12);$('monthly').setAttribute('aria-pressed',period===1);$('yearly').setAttribute('aria-pressed',period===12)}
function savedUI(){$('saved').replaceChildren();$('empty').hidden=saved.length>0;saved.forEach((s,i)=>{const el=document.createElement('article');el.className='saved-item';const title=document.createElement('h3');title.textContent=s.name;const total=document.createElement('strong');total.textContent=eur(s.total/12)+'/мес';const p=document.createElement('p');p.textContent=`С потерей стоимости: ${eur(s.full/12)}/мес · ${s.km.toLocaleString('ru-RU')} км/год · ${s.province||''}`;const remove=document.createElement('button');remove.textContent='Удалить расчёт';remove.onclick=()=>{saved.splice(i,1);persist();savedUI()};el.append(title,total,p,remove);$('saved').append(el)})}
function persist(){try{localStorage.setItem('autobudget-comparisons',JSON.stringify(saved))}catch{$('empty').hidden=false;$('empty').textContent='Сохранение в браузере недоступно; сравнение работает до закрытия страницы.'}}
$('model').onchange=selectModel;$('fuel').onchange=()=>{fuelUI();$('consumption').value=$('fuel').value==='electric'?18:6.5;$('energyPrice').value=$('fuel').value==='electric'?.35:$('fuel').value==='diesel'?1.85:2.1;estimateTax();render()};$('weight').oninput=()=>{estimateTax();render()};$('tax').oninput=()=>{taxNote(true);render()};$('province').onchange=()=>{taxNote(true);render()};$('coverage').onchange=()=>{$('insurance').value={wa:45,plus:60,all:85}[$('coverage').value];render()};document.querySelectorAll('input[type=number],input[type=range]').forEach(el=>{el.addEventListener('input',()=>{if(el.type!=='range'&&el.value!==''&&Number(el.value)<0)el.value=0;if(el.max&&Number(el.value)>Number(el.max))el.value=el.max;render()})});$('monthly').onclick=()=>{period=1;render()};$('yearly').onclick=()=>{period=12;render()};$('save').onclick=()=>{if(saved.length>=3)saved.shift();saved.push({...current});persist();savedUI();$('save').textContent='✓ Сохранено для сравнения';setTimeout(()=>$('save').textContent='＋ Сохранить для сравнения',1600)};selectModel();savedUI();
